import React, { useState, useMemo, useRef, useCallback } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { CompactEditor, stripHtml } from './SimpleEditor';
import MentionPicker, { renderMentions } from './MentionPicker';

// ── Entry types ───────────────────────────────────────────────────
const ENTRY_TYPES = {
  observation: { label: 'Observation', icon: '◎', color: '#2c5f8a', bg: '#e8eff8' },
  connection:  { label: 'Connection',  icon: '⟶', color: '#7b3fa0', bg: '#f0e8f8' },
  question:    { label: 'Question',    icon: '?',  color: '#b07d28', bg: '#faf0dc' },
  insight:     { label: 'Insight',     icon: '✦',  color: '#2e7d5e', bg: '#e4f4ec' },
  revision:    { label: 'Revision',    icon: '↺',  color: '#c0392b', bg: '#faeae8' },
  thread:      { label: 'Thread',      icon: '⊛',  color: '#1a5c3a', bg: '#e0f0e8' },
};

// Seeded rotation so cards always appear at same angle
function seedRotation(id) {
  let h = 0;
  for (let i = 0; i < id.length; i++) h = (Math.imul(31, h) + id.charCodeAt(i)) | 0;
  return ((h % 5) - 2) * 0.6; // -1.2 to 1.2 degrees
}

// ── Promote modal ─────────────────────────────────────────────────
function PromoteModal({ entry, investigations, onPromoteToExisting, onPromoteNew, onClose }) {
  const [mode, setMode]       = useState('existing'); // 'existing' | 'new'
  const [selectedInv, setSelectedInv] = useState('');
  const [logType, setLogType] = useState('insight');
  const [newTitle, setNewTitle] = useState('');

  const LOG_TYPES_SIMPLE = [
    { id: 'note',    label: 'Note' },
    { id: 'insight', label: 'Insight' },
    { id: 'revised', label: 'Position revised' },
    { id: 'evidence',label: 'Evidence added' },
  ];

  return (
    <div onClick={e => e.target === e.currentTarget && onClose()}
      style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.45)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 500, padding: 20 }}>
      <div style={{ background: 'var(--paper-card)', borderRadius: 12, width: '100%', maxWidth: 440, boxShadow: 'var(--shadow-md)', overflow: 'hidden' }}>
        <div style={{ padding: '14px 18px 12px', borderBottom: '1px solid var(--paper-3)', display: 'flex', justifyContent: 'space-between', alignItems: 'center', background: 'var(--paper-2)' }}>
          <span style={{ fontSize: 13, fontWeight: 600, color: 'var(--ink)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.04em' }}>→ PROMOTE TO INVESTIGATION</span>
          <button onClick={onClose} style={{ fontSize: 12, color: 'var(--ink-4)', background: 'none', border: 'none', cursor: 'pointer' }}>✕</button>
        </div>
        <div style={{ padding: '16px 18px' }}>
          {/* Entry preview */}
          <div style={{ background: 'var(--paper-2)', border: '1px solid var(--paper-3)', borderRadius: 7, padding: '10px 12px', marginBottom: 16, fontSize: 12, color: 'var(--ink-3)', lineHeight: 1.6, fontStyle: 'italic' }}>
            {stripHtml(entry.text).slice(0, 120)}{stripHtml(entry.text).length > 120 ? '…' : ''}
          </div>

          {/* Mode toggle */}
          <div style={{ display: 'flex', border: '1px solid var(--paper-3)', borderRadius: 7, overflow: 'hidden', marginBottom: 16 }}>
            {[['existing', 'Add to existing case'], ['new', 'Open as new case']].map(([m, label]) => (
              <button key={m} onClick={() => setMode(m)}
                style={{ flex: 1, padding: '7px 8px', fontSize: 11, border: 'none', borderRight: m === 'existing' ? '1px solid var(--paper-3)' : 'none', background: mode === m ? 'var(--accent-light)' : 'transparent', color: mode === m ? 'var(--accent)' : 'var(--ink-3)', cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
                {label}
              </button>
            ))}
          </div>

          {mode === 'existing' ? (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
              <select value={selectedInv} onChange={e => setSelectedInv(e.target.value)}
                style={{ padding: '8px 10px', fontSize: 13, borderRadius: 6, border: '1px solid var(--paper-3)', background: 'var(--paper-2)', color: 'var(--ink)' }}>
                <option value="">Select a case…</option>
                {investigations.map(inv => (
                  <option key={inv.id} value={inv.id}>{inv.caseNumber ? `${inv.caseNumber} — ` : ''}{inv.title}</option>
                ))}
              </select>
              <select value={logType} onChange={e => setLogType(e.target.value)}
                style={{ padding: '8px 10px', fontSize: 13, borderRadius: 6, border: '1px solid var(--paper-3)', background: 'var(--paper-2)', color: 'var(--ink)' }}>
                {LOG_TYPES_SIMPLE.map(t => <option key={t.id} value={t.id}>{t.label}</option>)}
              </select>
              <button disabled={!selectedInv} onClick={() => onPromoteToExisting(selectedInv, logType)}
                style={{ padding: '8px 16px', borderRadius: 7, background: selectedInv ? 'var(--accent)' : 'var(--paper-3)', color: selectedInv ? 'var(--paper-card)' : 'var(--ink-4)', border: 'none', cursor: selectedInv ? 'pointer' : 'not-allowed', fontSize: 13, fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
                Add to custody log →
              </button>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
              <input value={newTitle} onChange={e => setNewTitle(e.target.value)}
                placeholder="Case title…"
                style={{ padding: '8px 10px', fontSize: 13, borderRadius: 6, border: '1px solid var(--paper-3)', background: 'var(--paper-2)', color: 'var(--ink)' }} />
              <button disabled={!newTitle.trim()} onClick={() => onPromoteNew(newTitle)}
                style={{ padding: '8px 16px', borderRadius: 7, background: newTitle.trim() ? 'var(--accent)' : 'var(--paper-3)', color: newTitle.trim() ? 'var(--paper-card)' : 'var(--ink-4)', border: 'none', cursor: newTitle.trim() ? 'pointer' : 'not-allowed', fontSize: 13, fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
                Open new case →
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

// ── Entry card ────────────────────────────────────────────────────
function EntryCard({ entry, books, investigations, onDelete, onUpdate, onPromote, isQuick }) {
  const et  = ENTRY_TYPES[entry.type] || ENTRY_TYPES.observation;
  const rot = seedRotation(entry.id);
  const linkedBooks = books.filter(b => (entry.bookIds || []).includes(b.id));
  const [editing, setEditing]   = useState(false);
  const [draftText, setDraftText] = useState(entry.text || '');
  const [hovered, setHovered]   = useState(false);

  const promotedInv = entry.promoted?.investigationId
    ? investigations.find(i => i.id === entry.promoted.investigationId)
    : null;

  const commitEdit = () => {
    onUpdate({ ...entry, text: draftText, updatedAt: new Date().toISOString() });
    setEditing(false);
  };

  // Card size based on content
  const textLen = stripHtml(entry.text || '').length;
  const isLarge = textLen > 120;

  return (
    <div
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{
        background: isQuick ? (et.bg + '55') : 'var(--paper-card)',
        border: `1px solid ${et.color}33`,
        borderLeft: `3px solid ${et.color}`,
        borderRadius: isQuick ? 6 : 8,
        padding: isQuick ? '8px 12px' : '14px 16px',
        position: 'relative',
        transform: `rotate(${rot}deg)`,
        transition: 'transform 0.15s, box-shadow 0.15s',
        boxShadow: hovered ? `2px 4px 12px rgba(0,0,0,0.12), 0 0 0 1px ${et.color}33` : '1px 2px 5px rgba(0,0,0,0.07)',
        cursor: 'default',
        breakInside: 'avoid',
      }}
      onMouseOver={e => { e.currentTarget.style.transform = 'rotate(0deg) scale(1.01)'; e.currentTarget.style.zIndex = 2; }}
      onMouseOut={e => { e.currentTarget.style.transform = `rotate(${rot}deg)`; e.currentTarget.style.zIndex = 1; }}
    >
      {/* Type badge */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: isQuick ? 4 : 8 }}>
        <span style={{ fontSize: 11, color: et.color, fontFamily: 'var(--font-mono)', fontStyle: 'normal', fontWeight: 700 }}>{et.icon}</span>
        <span style={{ fontSize: 9, color: et.color, fontFamily: 'var(--font-mono)', fontStyle: 'normal', textTransform: 'uppercase', letterSpacing: '0.07em' }}>{et.label}</span>
        <span style={{ fontSize: 9, color: 'var(--ink-4)', fontStyle: 'italic', marginLeft: 'auto' }}>
          {new Date(entry.createdAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}
        </span>
      </div>

      {/* Content */}
      {editing ? (
        <div>
          <CompactEditor value={draftText} onChange={setDraftText} minHeight={60} autoFocus />
          <div style={{ display: 'flex', gap: 6, marginTop: 8 }}>
            <button onClick={commitEdit} style={{ fontSize: 11, padding: '4px 14px', borderRadius: 5, background: 'var(--accent)', color: 'var(--paper-card)', border: 'none', cursor: 'pointer' }}>Save</button>
            <button onClick={() => { setDraftText(entry.text); setEditing(false); }} style={{ fontSize: 11, padding: '4px 10px', borderRadius: 5, border: '1px solid var(--paper-3)', color: 'var(--ink-4)', cursor: 'pointer', background: 'transparent' }}>Cancel</button>
          </div>
        </div>
      ) : (
        <div style={{ fontSize: isQuick ? 12 : 13, color: 'var(--ink)', lineHeight: 1.65 }}
          dangerouslySetInnerHTML={{ __html: entry.text || '' }} />
      )}

      {/* Linked books */}
      {linkedBooks.length > 0 && !editing && (
        <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap', marginTop: 8 }}>
          {linkedBooks.map(b => (
            <span key={b.id} style={{ display: 'inline-flex', alignItems: 'center', gap: 3, fontSize: 9, color: b.color, fontStyle: 'italic' }}>
              <div style={{ width: 5, height: 5, borderRadius: '50%', background: b.color, flexShrink: 0 }} />
              {b.title}
            </span>
          ))}
        </div>
      )}

      {/* Tags */}
      {entry.tags?.length > 0 && !editing && (
        <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap', marginTop: 5 }}>
          {entry.tags.map(t => (
            <span key={t} style={{ fontSize: 9, padding: '1px 6px', borderRadius: 8, background: 'var(--paper-3)', color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>#{t}</span>
          ))}
        </div>
      )}

      {/* Promoted badge */}
      {promotedInv && (
        <div style={{ marginTop: 6, fontSize: 9, color: '#2e7d5e', fontFamily: 'var(--font-mono)', fontStyle: 'normal', display: 'flex', alignItems: 'center', gap: 4 }}>
          <span>⊛</span>
          <span>→ {promotedInv.caseNumber || promotedInv.title}</span>
        </div>
      )}

      {/* Hover actions */}
      {!editing && hovered && (
        <div style={{ position: 'absolute', top: 6, right: 8, display: 'flex', gap: 4 }}>
          <button onClick={() => setEditing(true)}
            style={{ fontSize: 9, padding: '2px 7px', borderRadius: 4, border: '1px solid var(--paper-3)', color: 'var(--ink-4)', background: 'var(--paper-card)', cursor: 'pointer' }}
            onMouseEnter={e => e.currentTarget.style.color = 'var(--accent)'}
            onMouseLeave={e => e.currentTarget.style.color = 'var(--ink-4)'}>✎</button>
          {!entry.promoted && (
            <button onClick={() => onPromote(entry)}
              style={{ fontSize: 9, padding: '2px 7px', borderRadius: 4, border: '1px solid var(--paper-3)', color: 'var(--ink-4)', background: 'var(--paper-card)', cursor: 'pointer' }}
              onMouseEnter={e => e.currentTarget.style.color = '#2e7d5e'}
              onMouseLeave={e => e.currentTarget.style.color = 'var(--ink-4)'}>→ case</button>
          )}
          <button onClick={() => onDelete(entry.id)}
            style={{ fontSize: 9, padding: '2px 7px', borderRadius: 4, border: '1px solid var(--paper-3)', color: 'var(--ink-4)', background: 'var(--paper-card)', cursor: 'pointer' }}
            onMouseEnter={e => e.currentTarget.style.color = 'var(--red)'}
            onMouseLeave={e => e.currentTarget.style.color = 'var(--ink-4)'}>✕</button>
        </div>
      )}
    </div>
  );
}

// ── Main ReadingLog ───────────────────────────────────────────────
export default function ReadingLog({ entries = [], books = [], articles = [], investigations = [], topics = [], onAdd, onDelete, onUpdate, onUpdateInvestigations }) {
  const [quickText, setQuickText]       = useState('');
  const [quickType, setQuickType]       = useState('observation');
  const [quickBookId, setQuickBookId]   = useState('');
  const [quickTags, setQuickTags]       = useState('');

  const [showComposer, setShowComposer] = useState(false);
  const [compText, setCompText]         = useState('');
  const [compType, setCompType]         = useState('observation');
  const [compBookIds, setCompBookIds]   = useState([]);
  const [compTags, setCompTags]         = useState('');

  const [filterType, setFilterType]     = useState('all');
  const [filterTag, setFilterTag]       = useState('');
  const [search, setSearch]             = useState('');
  const [promotingEntry, setPromotingEntry] = useState(null);

  const quickRef = useRef();

  const allSources = [...books, ...articles];

  // All tags across all entries
  const allTags = useMemo(() => {
    const tagMap = {};
    entries.forEach(e => (e.tags||[]).forEach(t => { tagMap[t] = (tagMap[t]||0)+1; }));
    return Object.entries(tagMap).sort((a,b) => b[1]-a[1]);
  }, [entries]);

  // Filtered entries
  const filtered = useMemo(() => entries
    .filter(e => filterType === 'all' || e.type === filterType)
    .filter(e => !filterTag || (e.tags||[]).includes(filterTag))
    .filter(e => !search || stripHtml(e.text||'').toLowerCase().includes(search.toLowerCase()))
    .sort((a,b) => new Date(b.createdAt) - new Date(a.createdAt))
  , [entries, filterType, filterTag, search]);

  // Today's entries
  const todayCount = useMemo(() => {
    const today = new Date().toDateString();
    return entries.filter(e => new Date(e.createdAt).toDateString() === today).length;
  }, [entries]);

  // Open questions
  const openQuestions = entries.filter(e => e.type === 'question' && !e.promoted);

  // Active threads
  const threadEntries = entries.filter(e => e.type === 'thread');

  // Quick capture submit
  const submitQuick = useCallback(() => {
    if (!quickText.trim()) return;
    const tags = quickTags.split(',').map(t => t.trim().toLowerCase()).filter(Boolean);
    onAdd({
      id: uuidv4(),
      type: quickType,
      text: quickText.trim(),
      quickCapture: true,
      bookIds: quickBookId ? [quickBookId] : [],
      tags,
      promoted: null,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    });
    setQuickText(''); setQuickTags(''); setQuickBookId('');
    quickRef.current?.focus();
  }, [quickText, quickType, quickBookId, quickTags, onAdd]);

  // Reflection submit
  const submitReflection = useCallback(() => {
    if (!stripHtml(compText).trim()) return;
    const tags = compTags.split(',').map(t => t.trim().toLowerCase()).filter(Boolean);
    onAdd({
      id: uuidv4(),
      type: compType,
      text: compText,
      quickCapture: false,
      bookIds: compBookIds,
      tags,
      promoted: null,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    });
    setCompText(''); setCompTags(''); setCompBookIds([]);
    setShowComposer(false);
  }, [compText, compType, compBookIds, compTags, onAdd]);

  // Promote to existing investigation
  const handlePromoteExisting = (invId, logType) => {
    const inv = investigations.find(i => i.id === invId);
    if (!inv) return;
    const entry = promotingEntry;
    const custodyEntry = {
      id: uuidv4(),
      type: logType,
      note: stripHtml(entry.text).slice(0, 300),
      createdAt: new Date().toISOString(),
    };
    const updated = { ...inv, custodyLog: [...(inv.custodyLog||[]), custodyEntry], updatedAt: new Date().toISOString() };
    onUpdateInvestigations(prev => prev.map(i => i.id === invId ? updated : i));
    onUpdate({ ...entry, promoted: { investigationId: invId, custodyEntryId: custodyEntry.id } });
    setPromotingEntry(null);
  };

  // Promote to new investigation
  const handlePromoteNew = (title) => {
    const entry = promotingEntry;
    const invId = uuidv4();
    const custodyEntry = {
      id: uuidv4(), type: 'note',
      note: `Opened from reading log: ${stripHtml(entry.text).slice(0, 200)}`,
      createdAt: new Date().toISOString(),
    };
    const newInv = {
      id: invId,
      caseNumber: `CASE-${String(investigations.length + 1).padStart(4,'0')}`,
      title,
      type: investigations[0]?.type || '',
      status: 'active',
      summary: stripHtml(entry.text),
      hypothesis: '', hypothesisStatus: 'untested', hypothesisNotes: '',
      bookIds: entry.bookIds || [],
      bookNotes: [],
      actors: [], causes: [], tags: entry.tags || [],
      analysis: '', verdict: '',
      contradictions: [],
      custodyLog: [custodyEntry],
      argMap: { nodes: [], edges: [] },
      writing: { sections: [], thesisStatement: '' },
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };
    onUpdateInvestigations(prev => [...prev, newInv]);
    onUpdate({ ...entry, promoted: { investigationId: invId, custodyEntryId: custodyEntry.id } });
    setPromotingEntry(null);
  };

  const isDark = document.documentElement.getAttribute('data-theme') === 'dark';
  const corkBg = isDark ? '#1a1712' : '#f0e8d4';

  return (
    <div style={{ display: 'flex', height: '100%', background: corkBg, overflow: 'hidden' }}>

      {/* ── LEFT: capture + feed ─────────────────────────────── */}
      <div style={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>

        {/* ── CAPTURE AREA ─────────────────────────── */}
        <div style={{ padding: '12px 16px', borderBottom: `1px solid ${isDark?'#2a2520':'#d8cdb8'}`, background: isDark?'#1c1a15':'#e8dfc8', flexShrink: 0 }}>

          {/* Quick capture strip */}
          <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginBottom: showComposer ? 12 : 0 }}>
            <select value={quickType} onChange={e => setQuickType(e.target.value)}
              style={{ fontSize: 11, padding: '5px 6px', borderRadius: 5, border: '1px solid var(--paper-3)', background: ENTRY_TYPES[quickType].color + '18', color: ENTRY_TYPES[quickType].color, fontFamily: 'var(--font-mono)', fontStyle: 'normal', flexShrink: 0, cursor: 'pointer' }}>
              {Object.entries(ENTRY_TYPES).map(([k, v]) => (
                <option key={k} value={k}>{v.icon} {v.label}</option>
              ))}
            </select>
            <input ref={quickRef} value={quickText} onChange={e => setQuickText(e.target.value)}
              onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); submitQuick(); } }}
              placeholder="Capture a quick thought… (Enter to save)"
              style={{ flex: 1, padding: '6px 10px', fontSize: 13, borderRadius: 6, border: '1px solid var(--paper-3)', background: isDark?'#272420':'#fff', color: 'var(--ink)', fontFamily: 'var(--font-serif)', outline: 'none' }} />
            <select value={quickBookId} onChange={e => setQuickBookId(e.target.value)}
              style={{ fontSize: 11, padding: '5px 6px', borderRadius: 5, border: '1px solid var(--paper-3)', background: 'var(--paper-2)', color: 'var(--ink-3)', maxWidth: 140, flexShrink: 0 }}>
              <option value="">No source</option>
              {allSources.map(b => <option key={b.id} value={b.id}>{b.title}</option>)}
            </select>
            <button onClick={submitQuick}
              style={{ fontSize: 11, padding: '6px 14px', borderRadius: 6, background: 'var(--accent)', color: 'var(--paper-card)', border: 'none', cursor: 'pointer', flexShrink: 0, fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
              ↵
            </button>
            <button onClick={() => setShowComposer(s => !s)}
              style={{ fontSize: 11, padding: '6px 12px', borderRadius: 6, border: '1px solid var(--paper-3)', color: showComposer ? 'var(--accent)' : 'var(--ink-4)', background: showComposer ? 'var(--accent-light)' : 'transparent', cursor: 'pointer', flexShrink: 0, fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
              {showComposer ? '↑ close' : '✎ reflect'}
            </button>
          </div>

          {/* Reflection composer */}
          {showComposer && (
            <div style={{ background: isDark?'#272420':'#fffdf7', border: '1px solid var(--paper-3)', borderRadius: 8, padding: '14px 16px' }}>
              <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginBottom: 10, flexWrap: 'wrap' }}>
                <select value={compType} onChange={e => setCompType(e.target.value)}
                  style={{ fontSize: 11, padding: '4px 6px', borderRadius: 5, border: '1px solid var(--paper-3)', background: ENTRY_TYPES[compType].color + '18', color: ENTRY_TYPES[compType].color, fontFamily: 'var(--font-mono)', fontStyle: 'normal', cursor: 'pointer' }}>
                  {Object.entries(ENTRY_TYPES).map(([k, v]) => (
                    <option key={k} value={k}>{v.icon} {v.label}</option>
                  ))}
                </select>
                <div style={{ display: 'flex', gap: 5, flexWrap: 'wrap', flex: 1 }}>
                  {allSources.map(b => (
                    <button key={b.id} onClick={() => setCompBookIds(prev => prev.includes(b.id) ? prev.filter(x => x !== b.id) : [...prev, b.id])}
                      style={{ fontSize: 10, padding: '2px 8px', borderRadius: 12, border: `1px solid ${compBookIds.includes(b.id) ? b.color : 'var(--paper-3)'}`, background: compBookIds.includes(b.id) ? b.color + '22' : 'transparent', color: compBookIds.includes(b.id) ? b.color : 'var(--ink-4)', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 3 }}>
                      <div style={{ width: 5, height: 5, borderRadius: '50%', background: compBookIds.includes(b.id) ? b.color : 'var(--paper-3)' }} />
                      {b.title}
                    </button>
                  ))}
                </div>
              </div>
              <MentionPicker value={compText} onChange={setCompText}
                placeholder="Write a longer reflection… Type @ to link books, investigations, topics, or events"
                rows={5} books={books} investigations={investigations} topics={topics} events={[]} />
              <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginTop: 10 }}>
                <input value={compTags} onChange={e => setCompTags(e.target.value)}
                  placeholder="Tags (comma-separated)…"
                  style={{ flex: 1, padding: '5px 10px', fontSize: 12, borderRadius: 5, border: '1px solid var(--paper-3)', background: 'var(--paper-2)', color: 'var(--ink)', fontFamily: 'var(--font-serif)' }} />
                <button onClick={submitReflection}
                  style={{ fontSize: 12, padding: '6px 20px', borderRadius: 6, background: 'var(--accent)', color: 'var(--paper-card)', border: 'none', cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
                  Pin to log
                </button>
              </div>
            </div>
          )}
        </div>

        {/* ── FILTER BAR ─────────────────────────── */}
        <div style={{ padding: '7px 16px', borderBottom: `1px solid ${isDark?'#2a2520':'#d8cdb8'}`, display: 'flex', gap: 6, alignItems: 'center', flexWrap: 'wrap', flexShrink: 0, background: isDark?'#1e1c17':'#ede5d0' }}>
          <button onClick={() => { setFilterType('all'); setFilterTag(''); }}
            style={{ fontSize: 10, padding: '2px 9px', borderRadius: 12, border: `1px solid ${filterType==='all'&&!filterTag?'var(--accent)':'var(--paper-3)'}`, background: filterType==='all'&&!filterTag?'var(--accent-light)':'transparent', color: filterType==='all'&&!filterTag?'var(--accent)':'var(--ink-4)', cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
            All {entries.length}
          </button>
          {Object.entries(ENTRY_TYPES).map(([k, v]) => {
            const cnt = entries.filter(e => e.type === k).length;
            if (!cnt) return null;
            return (
              <button key={k} onClick={() => setFilterType(filterType === k ? 'all' : k)}
                style={{ fontSize: 10, padding: '2px 9px', borderRadius: 12, border: `1px solid ${filterType===k?v.color:'var(--paper-3)'}`, background: filterType===k?v.color+'22':'transparent', color: filterType===k?v.color:'var(--ink-4)', cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
                {v.icon} {v.label} {cnt}
              </button>
            );
          })}
          <div style={{ marginLeft: 'auto' }}>
            <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search…"
              style={{ padding: '4px 10px', fontSize: 11, borderRadius: 5, border: '1px solid var(--paper-3)', background: isDark?'#272420':'#fff', color: 'var(--ink)', width: 130 }} />
          </div>
        </div>

        {/* ── PINBOARD FEED ──────────────────────── */}
        <div style={{ flex: 1, overflowY: 'auto', padding: '16px 16px' }}>
          {filtered.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '60px 20px', color: 'var(--ink-4)' }}>
              <div style={{ fontSize: 32, marginBottom: 12, opacity: 0.3 }}>◎</div>
              <div style={{ fontSize: 14, fontStyle: 'italic', lineHeight: 1.65 }}>
                {entries.length === 0
                  ? 'The log is empty.\nCapture your first thought above.'
                  : 'No entries match.'}
              </div>
            </div>
          ) : (
            <div style={{ columns: '280px', columnGap: 14 }}>
              {filtered.map(entry => (
                <div key={entry.id} style={{ marginBottom: 12, breakInside: 'avoid' }}>
                  <EntryCard
                    entry={entry}
                    books={books}
                    investigations={investigations}
                    onDelete={onDelete}
                    onUpdate={onUpdate}
                    onPromote={setPromotingEntry}
                    isQuick={entry.quickCapture} />
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* ── RIGHT: mind's index ──────────────────────────────── */}
      <div style={{ width: 240, borderLeft: `1px solid ${isDark?'#2a2520':'#d0c5b0'}`, overflowY: 'auto', background: isDark?'#1a1712':'#e8dfc8', padding: '16px 14px', flexShrink: 0 }}>

        {/* Daily summary */}
        <div style={{ background: isDark?'#272420':'#fffdf7', border: '1px solid var(--paper-3)', borderRadius: 8, padding: '12px 14px', marginBottom: 16 }}>
          <div style={{ fontSize: 9, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: 8 }}>
            {new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' })}
          </div>
          <div style={{ fontSize: 22, fontWeight: 700, color: 'var(--ink)', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{todayCount}</div>
          <div style={{ fontSize: 11, color: 'var(--ink-4)', fontStyle: 'italic' }}>entries today</div>
          <div style={{ marginTop: 8, display: 'flex', gap: 6, flexWrap: 'wrap' }}>
            {Object.entries(ENTRY_TYPES).map(([k, v]) => {
              const cnt = entries.filter(e => e.type === k && new Date(e.createdAt).toDateString() === new Date().toDateString()).length;
              if (!cnt) return null;
              return <span key={k} style={{ fontSize: 10, color: v.color, fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{v.icon}{cnt}</span>;
            })}
          </div>
        </div>

        {/* Open questions */}
        {openQuestions.length > 0 && (
          <div style={{ marginBottom: 16 }}>
            <div style={{ fontSize: 10, fontWeight: 700, color: '#b07d28', fontFamily: 'var(--font-mono)', fontStyle: 'normal', textTransform: 'uppercase', letterSpacing: '0.07em', marginBottom: 8, paddingBottom: 5, borderBottom: '1px solid #b07d2833' }}>
              ? Open questions ({openQuestions.length})
            </div>
            {openQuestions.slice(0, 5).map(e => (
              <div key={e.id} onClick={() => setFilterType('question')}
                style={{ fontSize: 11, color: 'var(--ink-3)', lineHeight: 1.5, marginBottom: 7, paddingLeft: 8, borderLeft: '2px solid #b07d2855', cursor: 'pointer' }}
                onMouseEnter={e2 => e2.currentTarget.style.color = '#b07d28'}
                onMouseLeave={e2 => e2.currentTarget.style.color = 'var(--ink-3)'}>
                {stripHtml(e.text).slice(0, 70)}{stripHtml(e.text).length > 70 ? '…' : ''}
              </div>
            ))}
          </div>
        )}

        {/* Active threads */}
        {threadEntries.length > 0 && (
          <div style={{ marginBottom: 16 }}>
            <div style={{ fontSize: 10, fontWeight: 700, color: '#1a5c3a', fontFamily: 'var(--font-mono)', fontStyle: 'normal', textTransform: 'uppercase', letterSpacing: '0.07em', marginBottom: 8, paddingBottom: 5, borderBottom: '1px solid #1a5c3a33' }}>
              ⊛ Threads ({threadEntries.length})
            </div>
            {threadEntries.slice(0, 4).map(e => (
              <div key={e.id} style={{ fontSize: 11, color: 'var(--ink-3)', lineHeight: 1.5, marginBottom: 7, paddingLeft: 8, borderLeft: '2px solid #1a5c3a55' }}>
                {stripHtml(e.text).slice(0, 70)}{stripHtml(e.text).length > 70 ? '…' : ''}
              </div>
            ))}
          </div>
        )}

        {/* Tags index */}
        {allTags.length > 0 && (
          <div>
            <div style={{ fontSize: 10, fontWeight: 700, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', textTransform: 'uppercase', letterSpacing: '0.07em', marginBottom: 8, paddingBottom: 5, borderBottom: '1px solid var(--paper-3)' }}>
              # Tags index
            </div>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 5 }}>
              {allTags.map(([tag, count]) => (
                <button key={tag} onClick={() => setFilterTag(filterTag === tag ? '' : tag)}
                  style={{ fontSize: 10, padding: '2px 8px', borderRadius: 10, border: `1px solid ${filterTag===tag?'var(--accent)':'var(--paper-3)'}`, background: filterTag===tag?'var(--accent-light)':'transparent', color: filterTag===tag?'var(--accent)':'var(--ink-4)', cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
                  #{tag} <span style={{ opacity: 0.6 }}>{count}</span>
                </button>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Promote modal */}
      {promotingEntry && (
        <PromoteModal
          entry={promotingEntry}
          investigations={investigations}
          onPromoteToExisting={handlePromoteExisting}
          onPromoteNew={handlePromoteNew}
          onClose={() => setPromotingEntry(null)} />
      )}
    </div>
  );
}
